"""Render B4's paraphrased evidence cards. Never reads or copies raw source prose."""
from pathlib import Path
import json
import os

ROOT = Path(__file__).resolve().parents[5]
OUT = Path(__file__).resolve().parent
DIG = 'docs/research/power-systems/wiki-digests/'
DUMP = DIG + 'full-dumps/'
NOV = 'docs/research/novels/full-book/'
cards = {}

def add(slug, title, rows, limits, basis=None, status='bounded evidence'):
    cards[slug] = dict(title=title, rows=rows, limits=limits,
                       basis=basis or DIG + 'DIGEST_' + slug + '.md', status=status)

def note(worker, n, title):
    return DUMP + 'workers/' + worker + '/NOTES.jsonl', f'JSONL line {n}, {title}'

def row(label, codes, fact, path, locator):
    return dict(label=label, codes=codes, fact=fact, path=path, locator=locator)

def nr(label, codes, fact, worker, n, title):
    return row(label, codes, fact, *note(worker, n, title))

