# Thin sources keep real body-related research leads without promoting them to facts.
def lead(slug, title, codes, fact, section, limits):
    add(slug, title, [row('inferred / unverified lead', codes, fact,
        DIG+'DIGEST_'+slug+'.md', section)], limits,
        status='lead only, canon qualification open')

