def link(path):
    if path.startswith('https://'):
        return f'[source]({path})'
    return f'[{Path(path).name}]({os.path.relpath(ROOT/path, OUT)})'

for slug,c in cards.items():
    lines=[f'# {c["title"]}: body and lineage catalog', '',
           '2026-10-14. B4 research return. Status: **'+c['status']+'**.', '',
           'Entry source: '+link(c['basis'])+'. Evidence labels follow [REPORT](REPORT.md). '
           'Mappings are analyst comparisons, not canon terminology or accepted game rules.', '',
           '| ID | Evidence | Genetics mapping | Bounded finding | Locator |',
           '|---|---|---|---|---|']
    for n,r in enumerate(c['rows'],1):
        lines.append(f'| C{n:02} | {r["label"]} | {r["codes"]} | {r["fact"]} | {link(r["path"])}: {r["locator"]} |')
    lines += ['', 'Coverage and contradictions: '+c['limits'], '',
              'Unmentioned BD/CL/BP/MX/CN/SG/AG/BM subcodes are **not established by this review**, '
              'rather than ruled out by the setting. In particular bodily sex, identity, presentation, '
              'reproductive function and legal/social eligibility must not be inferred from one another.', '']
    (OUT/f'SRC_{slug}.md').write_text('\n'.join(lines))

digests=sorted((ROOT/DIG).glob('DIGEST_*.md'))
inventory=[]
for p in digests:
    slug=p.stem.removeprefix('DIGEST_')
    inventory.append(dict(slug=slug, digest=str(p.relative_to(ROOT)),
        disposition=cards[slug]['status'] if slug in cards else 'skip: no relevant supported body/lineage finding in consulted digest',
        output=f'SRC_{slug}.md' if slug in cards else None))
(OUT/'COVERAGE.json').write_text(json.dumps(dict(date='2026-10-14',
    policy='Top-level current digests only; historical copies are not additional sources.',
    digests=inventory, supplemental=[s for s in cards if not any(p.stem=='DIGEST_'+s for p in digests)]), indent=2)+'\n')
print(f'{len(cards)} source cards; {len(digests)} current digests; {sum(x["output"] is None for x in inventory)} skips')
